/* 自動生成（tools/flash_to_js.py）。元＝career-master/research/gijutsushi-cards/flash/flash.json */
const NJ_PLAN_DATA = [{"f": "二次:計画", "q": "【第六次環境基本計画｜時期】第六次環境基本計画が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2024年5月（5月21日）。第五次ではなくこの第六次が最新版である<br><br><b>答案での使い方</b>　書き出しで最新版を明示する。第五次(R2題材)と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】第六次環境基本計画が掲げる2030年度の温室効果ガス削減目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2013年度比46%削減（さらに50%の高みに向け挑戦を続ける）<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさの根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】第六次環境基本計画が掲げる30by30目標とは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2030年までに陸と海の30%以上を保全する目標。ネイチャーポジティブ実現の手段<br><br><b>答案での使い方</b>　必須Ⅰ(2) 生物多様性の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】世界の年平均気温は産業革命前より何℃上昇した（2023年）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　1.45℃上昇（2023年）。気候危機の背景として示されている<br><br><b>答案での使い方</b>　必須Ⅰ(1) 冒頭で課題の背景を示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜柱】「環境・経済・社会の統合的向上」を実践する場と位置づけられた重点戦略は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　地域づくり。地域循環共生圏で地域脱炭素とネイチャーポジティブを同時に解決する<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の方向を国の言葉で言うときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜柱】「新たな成長」を導く重点戦略の中身は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　持続可能な生産と消費を実現するグリーンな経済システム。自然資本への投資拡大と環境価値の内部化<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策の方向づけに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】第六次環境基本計画を根拠に、自然資本投資の課題を『制度・政策』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　環境価値を市場価値に内部化するため、成長志向型CP構想の実行と税制のグリーン化を、競争力を損なわず設計する必要がある<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・政策の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】自然資本投資の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　サステナブルファイナンスと地域金融のESG化による資金動員が不可欠だが、評価指標が未成熟で資金が循環しにくい<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】計画の実践・実装の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　環境人材の育成や公正な移行への人的資本投資、地域循環共生圏を支える中間支援組織の担い手不足が制約になっている<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜解決策】地域ごとに異なる課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　地域循環共生圏の形成で、地域の自然資本を活かし近隣と資源を補完し合う自立・分散型の地域づくりを進める<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域系の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜解決策】環境価値の内部化に向けた解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　成長志向型カーボンプライシング構想で、先行投資を促しつつ炭素価格負担を段階的に導入し、脱炭素と競争力を両立する<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜リスク】30by30を急ぐ地域共生型再エネ拡大で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：景観・生態系への新たな環境負荷。対策：洋上・陸上風力の環境配慮の制度検討を計画の初期段階から組み込む<br><br><b>答案での使い方</b>　必須Ⅰ(3) 脱炭素と自然共生のトレードオフに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜注意】2035年度60%・2040年度73%削減は第六次環境基本計画の数字か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　違う。地球温暖化対策計画（2025年2月）の数字。第六次が明記するのは2030年度46%とCN2050<br><br><b>答案での使い方</b>　両計画の数字を混同すると減点。書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜時期】地球温暖化対策計画（現行）が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2025年2月（2021年10月の前計画を改定）。2035・2040年度目標はこの改定で新設<br><br><b>答案での使い方</b>　書き出しで最新版を明示。旧計画(2030年度のみ)と区別<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】地球温暖化対策計画の2030・2035・2040年度の削減目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2013年度比で2030年度46%（7.6億t）、2035年度60%（5.7億t）、2040年度73%（3.8億t）<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさと(2)の到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】2024年度の温室効果ガス排出・吸収量は何億t（2013年度比）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　9.94億t（2013年度比28.7%減）。初めて10億tを下回った（2026年4月発表）<br><br><b>答案での使い方</b>　必須Ⅰ(1) 現状と2030年度目標7.6億tとの差を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】家庭部門のエネルギー起源CO2の2030年度目安は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　71百万t（2013年度209百万tから66%減）<br><br><b>答案での使い方</b>　R8 Ⅰ-2の題材。全体目標46%と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜柱】地球温暖化対策計画の4本の柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　エネルギー転換／産業・業務・運輸等／地域・くらし／横断的取組<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の分野を国の分類で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜柱】横断的取組に位置づく施策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　成長志向型カーボンプライシング、循環経済移行、吸収源確保、国際貢献<br><br><b>答案での使い方</b>　必須Ⅰ(2) 横断的な解決策を挙げるときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】温暖化対策計画を根拠に、脱炭素化が難しい分野の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　水素・アンモニア・CCUS等による火力の脱炭素化や、航空・海運の次世代燃料の実用化に技術的ブレイクスルーが必要<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】脱炭素先行地域100以上の創出の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　計画策定・実施を担う自治体職員や事業者側の体制・人材の確保が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】2030年度目標とネットゼロを結ぶ道筋の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　中長期の予見可能性を高め、GX投資を加速する資金動員が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜解決策】火力発電の脱炭素化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　水素・アンモニア混焼やCCUSで火力を脱炭素化し、非効率石炭火力は計画的にフェードアウトする<br><br><b>答案での使い方</b>　必須Ⅰ(2) エネルギー転換の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜解決策】地域の脱炭素化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　脱炭素先行地域を2030年度までに100以上創出し、民生部門の電力CO2実質ゼロのモデルを全国へ広げる<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域・くらしの解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜リスク】石炭火力のフェードアウトを急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：代替電源の整備が追いつかず需給バランスに影響。対策：LNG火力を移行手段に使い、再エネ・原子力の最大活用を並行する<br><br><b>答案での使い方</b>　必須Ⅰ(3) エネルギー転換のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜注意】2035・2040年度の部門別CO2数値は確定値か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　確定値ではない。複数シナリオ分析に基づく幅のある「目安」<br><br><b>答案での使い方</b>　答案で確定値のように書くと減点。「目安」と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜時期】GX2040ビジョンと第7次エネルギー基本計画の閣議決定はいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　いずれも2025年2月18日。別の文書で、GX2040は2023年7月の戦略の改訂版<br><br><b>答案での使い方</b>　書き出しで最新版を明示。2文書を混ぜない<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜時期】排出量取引制度が本格稼働（義務化）する年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2026年度。2023年度開始の自主参加型GXリーグとは別<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰで「義務化済み」と書く根拠に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜目標】2040年度の電源構成（目安）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　再エネ4〜5割程度、火力3〜4割程度、原子力2割程度。2022年度は再エネ21.8%、火力72.6%<br><br><b>答案での使い方</b>　必須Ⅰ(1) 現状との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.enecho.meti.go.jp/category/others/basic_plan/pdf/20250218_03.pdf\" target=\"_blank\" rel=\"noopener\">資源エネルギー庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜目標】GX経済移行債の規模と、呼び込む官民投資の規模は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　10年間で20兆円規模の先行投資支援により、150兆円規模の官民投資を呼び込む<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資金面の解決策の規模感に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜柱】GX2040ビジョンの柱のうち、カーボンプライシングの柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　成長志向型カーボンプライシング構想。排出量取引制度の本格稼働と化石燃料賦課金（2028年度）で炭素価格を形成<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策の国の言葉に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜柱】GX2040ビジョンの「GX産業立地」の考え方は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　脱炭素電源を見据えた産業集積の加速と、地域に利益が及ぶ地域GXを進める<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅲ 地域系の解決策の方向づけに<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】再エネ主力電源化（2040年度4〜5割）の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　出力変動を調整する系統整備・蓄電池・次世代革新炉など複数技術の同時確立が必要で、単一技術では対応できない<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】排出量取引制度の義務化の課題を『制度』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　公平性確保のため、業種別の無償割当ルールと価格安定化措置（上限・下限価格）の制度設計が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】中堅・中小企業のGX対応の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　大企業に比べ支援機関・資金・人材が不足し、排出量の見える化や設備高度化の対応力の差が広がりやすい<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】排出量取引制度による解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　排出枠の無償割当てと取引で炭素価格を形成し、多排出産業の投資と構造転換を促す<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】再エネ主力電源化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　S+3Eを前提に、系統整備・蓄電池・次世代革新炉・火力の脱炭素化を並行して進める<br><br><b>答案での使い方</b>　必須Ⅰ(2) エネルギー面の解決策に<br><br>【出典】<a href=\"https://www.enecho.meti.go.jp/category/others/basic_plan/pdf/20250218_03.pdf\" target=\"_blank\" rel=\"noopener\">資源エネルギー庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】データセンター立地等の合意形成の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　地域GX（地域裨益型・地域共生型）で、脱炭素電源の利益を地域に還元し、自治体と連携して地方創生につなげる<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域系の解決策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜リスク】排出量取引制度の義務化で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：多排出産業の競争力低下と海外移転（カーボンリーケージ）。対策：政府指針による業種配慮の無償割当てと移行期の投資余力確保<br><br><b>答案での使い方</b>　必須Ⅰ(3) 制度導入のリスクと対策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜注意】2035年度60%・2040年度73%削減と、R8 Ⅰ-2の家庭部門66%の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　60%・73%は全体（2013年度比）、66%は家庭部門（2030年度）。母集団が違う<br><br><b>答案での使い方</b>　数字は母集団とセットで書く。取り違えは減点<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜時期】気候変動適応計画の閣議決定と一部変更はいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2021年10月に閣議決定、2023年5月に一部変更。一部変更で熱中症対策実行計画が第4章に追加<br><br><b>答案での使い方</b>　書き出しで版を明示。熱中症対策は第4章の内容として書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜時期】気候変動適応計画の次の改定の見通しは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2026年2月の第3次影響評価報告書を受け、2026年度内に改定予定。骨子は2026年6月<br><br><b>答案での使い方</b>　書き出しで「改定予定」と書き、旧版との取り違えを避ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜目標】熱中症対策実行計画の中期目標（2030年）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　熱中症死亡者数（5年移動平均）を、令和4年概数の1,295名から半減<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜目標】熱中症死亡者数の実績は目標の基準値と比べてどうか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　令和5年1,651人、令和6年2,160人と、基準値1,295名を大きく上回り増加（人口動態統計確定数）<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさを示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜柱】適応計画の7つの基本戦略は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　施策への組み込み、科学的知見、情報基盤、地域推進、事業者等の促進、国際貢献、関係機関連携<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の方向を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜柱】適応計画で「地域の実情に応じた適応」を進める仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　地域気候変動適応計画と地域適応センター。国立環境研究所が情報基盤A-PLATで支援<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-2 地域施策の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】地域の適応推進の課題を『制度・政策』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　地域適応計画の策定が努力義務にとどまるため、地域適応センターの設置を含む制度的な推進力の確保が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・政策の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】適応策の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　事業者の気候リスク対応投資を促し、適応ビジネスをどう資金面で後押しするかが課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】適応策の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　農業の高温耐性品種の開発・普及と、流域治水やグリーンインフラによるハード・ソフト一体の防災技術の高度化が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜解決策】水害リスクの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　流域治水で、河川整備に加え流域全体の関係者が協働し、ハード・ソフト一体で水害リスクを下げる<br><br><b>答案での使い方</b>　必須Ⅰ(2) 自然災害分野の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜解決策】熱中症の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　熱中症警戒情報・特別警戒情報（WBGT基準）の発表と、指定暑熱避難施設の開放で、高齢者等の被害を防ぐ<br><br><b>答案での使い方</b>　必須Ⅰ(2) 健康分野の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜リスク】流域治水の大規模投資で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：財政負担の拡大と生態系の分断など新たな環境影響。対策：グリーンインフラやNbSを組み合わせ環境配慮型の整備を優先する<br><br><b>答案での使い方</b>　必須Ⅰ(3) ハード整備のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜リスク】地域適応計画が努力義務であることで生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：小規模市町村で策定が進まず地域間の適応力が開く。対策：広域協議会を通じ都道府県が市町村を技術的・財政的に支援<br><br><b>答案での使い方</b>　必須Ⅰ(3)・Ⅱ-2 自治体支援の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜注意】適応計画の「7分野」と「7つの基本戦略」は同じか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　別物。7分野は農林水産業・水環境・自然生態系・自然災害・健康・産業経済・国民生活の分野別施策<br><br><b>答案での使い方</b>　どちらも7個。分野を問う設問に戦略を書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜時期】生物多様性国家戦略2023-2030が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2023年3月（31日）。第六次環境基本計画（2024年5月）とは別の計画<br><br><b>答案での使い方</b>　書き出しで版を明示。R6・R8 Ⅰ-1で出題<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜目標】30by30は国家戦略のどの目標に位置づく？その内容は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　行動目標1-1。2030年までに陸と海の30%以上を保護地域・OECMで保全<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の到達点に。戦略そのものではない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜目標】中間評価（2026年2月）の保護地域・OECM占有率は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　陸域21.0%（2025年時点）、海域13.3%（2021年以降変化なし）。目標は各30%<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000379260.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜柱】国家戦略の基本戦略1〜3は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　①生態系の健全性の回復、②自然を活用した社会課題の解決、③ネイチャーポジティブ経済の実現<br><br><b>答案での使い方</b>　R6 Ⅰ-1の3戦略。解決策の方向を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜柱】基本戦略4と5は？また目標の構成数は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　4：生活・消費活動での価値の認識と行動、5：基盤整備と国際連携。5基本戦略・15状態目標・25行動目標<br><br><b>答案での使い方</b>　3戦略は全体の一部。設問の範囲を確認する<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】30by30達成の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　OECMとして整理できる区域を見極める評価手法が未確立で、自然共生サイトの認定基準・モニタリング手法の標準化が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】ネイチャーポジティブ経営の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　自然資本の損失の外部不経済を価格に反映する経済的手法が実証段階にとどまり、民間資金の誘導が不十分<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】里山・森林の保全の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　森林・農地・里山の管理の担い手が不足し、担い手の確保・育成と地域主体の取組を支えるインセンティブ設計が必要<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】民間の取組を生かす30by30の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　自然共生サイト（日本版OECM）で、民間等が保全する区域を国が認定し、国際データベースに登録する<br><br><b>答案での使い方</b>　必須Ⅰ(2) 30by30の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】企業の自然資本対応の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　TNFDによる自然関連リスク・機会の情報開示を促し、ESG金融と結び付けてネイチャーポジティブ経済へ移行する<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】社会課題と自然保全を両立する解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　グリーンインフラや生態系ネットワークで、防災・気候変動対応と生物の移動・遺伝的多様性の維持を両立する<br><br><b>答案での使い方</b>　必須Ⅰ(2) 自然活用の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜リスク】30by30を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：住民のなりわいとの調整不足で反発を招く。対策：自然共生サイト認定や保護地域拡張時に事前協議プロセスを制度化する<br><br><b>答案での使い方</b>　必須Ⅰ(3) 合意形成のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜リスク】不適正な再エネ導入がもたらすリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：生態系への悪影響で脱炭素と保全がトレードオフに。対策：環境影響評価とゾーニング、地域共生型再エネの導入<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再エネとの両立のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜注意】OECMと自然共生サイトの違いは？また30by30は戦略の別名か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　OECMは国際的な保全区分、自然共生サイトは国が認定する日本版。30by30は目標の一つで戦略の別名ではない<br><br><b>答案での使い方</b>　定義の書き分けで減点を避ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜時期】第五次循環型社会形成推進基本計画が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2024年8月（2日）。副題は「循環経済を国家戦略に」<br><br><b>答案での使い方</b>　書き出しで最新版を明示。第四次と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】2030年度の資源生産性・資源消費量・最終処分量の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　資源生産性約60万円/t、一人当たり天然資源消費量約11t/人・年、最終処分量約1,100万t/年<br><br><b>答案での使い方</b>　必須Ⅰ(1)(2) 現状との差と到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】2030年度の循環利用率と再生資源の投入割合の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　入口側約19%、出口側約44%。再生可能資源・循環資源の投入割合は約34%<br><br><b>答案での使い方</b>　入口と出口の数字を取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】循環経済関連ビジネスの市場規模目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2030年までに80兆円以上、2050年に120兆円（2020年は約50兆円）<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜柱】第五次循環基本計画の5つの重点分野は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　①循環経済への移行②事業者間連携③地域の循環システム④基盤強靱化⑤国際資源循環<br><br><b>答案での使い方</b>　R7 Ⅰ-2は②③⑤の3つ。解決策の方向を国の言葉で<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜柱】動静脈連携とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　製造・小売の動脈産業と廃棄物処理・リサイクルの静脈産業が連携し、再生材利用の拡大と市場創出を図る取組<br><br><b>答案での使い方</b>　必須Ⅰ(2) 事業者間連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】動静脈連携の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　再生材の品質の共通認識づくりと、デジタル製品パスポート対応のデータベースなど、循環性を計測・開示する技術基盤が未整備<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】資源循環の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　人口減少で廃棄物処理・資源循環のエッセンシャルワーカーが不足し、中小企業が大半の処理業者への影響が大きい<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】市場規模80兆円の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　短期的には経済合理的でない動静脈連携への投資を、GX投資等で後押しする資金誘導が必要<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜解決策】再生材の利用拡大の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　動静脈連携で再生材利用を広げ、デジタル製品パスポート（DPP）で原材料・リサイクル性の情報を開示する<br><br><b>答案での使い方</b>　必須Ⅰ(2) 技術・制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜解決策】地域の循環の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　地域の資源の地産地消・循環を進め、製造業・処理業と自治体・市民が連携する地域の循環システムで地方創生につなげる<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-2 地域施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜リスク】動静脈連携で再生材を急拡大するリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：品質管理や有害物質管理が不十分なまま流通。対策：製品安全・有害物質のリスク管理・不法投棄防止を伴う適正な取組を求める<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再生材拡大のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜注意】第五次の数値目標の年次と、第四次との違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　目標年次は2030年度。第四次は指標が151あったが、第五次は指標数を絞り込んだ<br><br><b>答案での使い方</b>　旧計画の指標数・目標値で答案を書かない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜時期】地域脱炭素ロードマップの決定はいつで、決定主体は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2021年6月9日、国・地方脱炭素実現会議の決定。閣議決定ではない<br><br><b>答案での使い方</b>　R6 Ⅰ-2で出題。書き出しで決定主体を正確に書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜時期】脱炭素先行地域の現在の年限の整理は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2025年度までに少なくとも100か所を選定し、2030年度までに実行<br><br><b>答案での使い方</b>　選定年と実行年を取り違えない。当初は「2030年度までに100か所」<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜定義】脱炭素先行地域の定義の核は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　民生部門（家庭部門及び業務その他部門）の電力消費に伴うCO2排出の実質ゼロ。運輸・熱利用等は地域特性に応じて実施<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-1 定義を問われたときの書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜目標】脱炭素先行地域の選定状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　第7回（2026年2月）までに45道府県133市町村の102提案が選定。3提案が辞退<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標100か所との差・辞退を課題の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜目標】重点対策①自家消費型太陽光の導入目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2030年に設置可能な建築物の約50%、2040年に100%<br><br><b>答案での使い方</b>　必須Ⅰ(2) 太陽光の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜柱】ロードマップの8つの重点対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　①自家消費型太陽光②地域共生型再エネ③業務ビルZEB化④住宅省エネ⑤ゼロカーボン・ドライブ⑥資源循環⑦まちづくり⑧農林水産業<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策を国の分類で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】地域脱炭素の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　太陽光自家消費・ZEB・ZEH・電動車を全国に普及させるには、低圧需要での経済性確保と初期投資ゼロの導入モデルの確立が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】地域脱炭素の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　先行地域の計画策定・実施を担う自治体職員や地元企業・金融機関の体制確保が、地域間の取組差を生んでいる<br><br><b>答案での使い方</b>　必須Ⅰ(1)・Ⅱ-2 人材の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】再エネ促進区域設定の課題を『合意形成』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　地域協議会の開催等による合意形成が必要で、環境配慮や地域貢献の要件設定を円滑に進める仕組みが課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 合意形成・地域の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜解決策】合意形成が進まない課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　促進区域の設定（ポジティブゾーニング）で、環境配慮と地域貢献の要件を付けて適地を事前に示す<br><br><b>答案での使い方</b>　必須Ⅰ(2) 再エネ立地の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜解決策】自治体の取組を後押しする解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　重点対策加速化事業（地域脱炭素移行・再エネ推進交付金）で、重点対策を組み合わせた複数年の計画を5年間支援する<br><br><b>答案での使い方</b>　必須Ⅰ(2)・Ⅱ-2 財政支援の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜リスク】先行地域の選定数を優先して生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：コスト増や地元合意の難航で辞退が出る。対策：計画段階から地域協議会と要件明確化を徹底し、実行可能性を精査して選定<br><br><b>答案での使い方</b>　必須Ⅰ(3) 目標優先のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜リスク】促進区域の設定を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：合意形成が不十分なまま区域指定が進み、住民と対立。対策：地域協議会で環境保全と地域の経済・社会課題の解決を併せて検討<br><br><b>答案での使い方</b>　必須Ⅰ(3)・Ⅱ-2 合意形成のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜注意】重点対策加速化事業の交付対象は、8つの重点対策のどれか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　①〜⑤のみ。⑥資源循環・⑦まちづくり・⑧農林水産業は対象外<br><br><b>答案での使い方</b>　「重点対策＝すべて交付金対象」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜時期】令和8年版の環境白書等が閣議決定されたのはいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2026年6月（5日）。環境の日に合わせて公表された、3白書の合冊<br><br><b>答案での使い方</b>　書き出しで最新版を明示。令和7年版と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜時期】令和8年版白書のテーマは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　循環経済（サーキュラーエコノミー）で日本列島を強く豊かに<br><br><b>答案での使い方</b>　令和7年版（グリーンな経済システム）と取り違えると減点<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜目標】循環経済行動計画が目指す2030年までの投資規模は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　再資源化拠点等の構築・ネットワーク形成に向け、官民で約1兆円<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資金面の解決策の規模感に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜目標】令和8年版白書の保護地域・OECM指定割合（2025年8月）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　陸地約21.0%、海洋約13.3%。目標は2030年までに各30%以上<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜柱】循環経済行動計画（2026年4月決定）の2つの柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　再生資源供給サプライチェーンの強靱化と、日本をハブとする国際資源循環ネットワークの構築<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資源循環の解決策を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜柱】大規模太陽光（メガソーラー）の対策パッケージの考え方は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　不適切事案への法的規制の強化と、地域共生型への支援強化を両立させる<br><br><b>答案での使い方</b>　必須Ⅰ(2)・Ⅲ 再エネ立地の方向づけに<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】重要鉱物・金属の再生資源供給の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　重要鉱物・金属を質・量・コスト面で安定供給するための再資源化・製錬技術の確立が必要で、動脈と静脈をつなぐ技術基盤が不足<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】再資源化拠点の整備の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　官民で約1兆円の投資を目指すが、再生材需要の創出を起点とした自律的な市場形成の設計が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】メガソーラーの課題を『合意形成』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　不適切事案への規制強化と地域共生型への支援を両立させる必要があり、地域住民との合意形成が課題<br><br><b>答案での使い方</b>　必須Ⅰ(1) 合意形成・地域の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜解決策】資源循環の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　再生資源供給サプライチェーンの強靱化で、再資源化拠点を構築・ネットワーク化し、再生材を質・量・コスト面で安定供給する<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資源循環の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜解決策】自然再興の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　自然共生サイトの認定（地域生物多様性増進法、2025年4月施行）で、民間等の保全区域を国が認定し30by30を進める<br><br><b>答案での使い方</b>　必須Ⅰ(2) 生物多様性の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜リスク】再資源化拠点の構築を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：環境対策が不十分なスクラップヤード経由で循環資源が海外へ流出。対策：許可制導入とバーゼル法手続の適正化で監視強化<br><br><b>答案での使い方</b>　必須Ⅰ(3) 資源循環のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜リスク】メガソーラー拡大のリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　リスク：自然再興と土地利用で競合し、不適切な開発を招く。対策：対策パッケージで規制を強化し、地域共生型への支援を重点化<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再エネと自然保全の両立に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜注意】令和8年版の「約1兆円」と、GX2040の「150兆円」の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　1兆円は循環経済行動計画（再資源化拠点）、150兆円はGX全体の官民投資。母集団が違う<br><br><b>答案での使い方</b>　数字は何の目標かとセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}];
const NJ_TERM_DATA = [{"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜時期】排出量取引制度は本格稼働しているか。何年度からか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2026年度（2026年4月1日施行）。2023年度開始の自主参加型GXリーグとは別の、法定の制度<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す。GXリーグと区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜定義】排出量取引制度とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　政府が排出枠（CO2 1t＝1枠）を無償割当てし、排出実績量と同量の枠の保有を義務づけ、過不足を事業者間で取引できる制度<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜制度】排出量取引制度の対象事業者の要件は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　CO2の直接排出量の直近3年度平均が10万トン以上の事業者。事業者単位で判定する<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。数字は「3年度平均10万t」<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505CO0000000379\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜制度】排出量取引制度の価格安定の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　参考上限取引価格と調整基準取引価格を毎年度設定。償却不足分は「未償却量×参考上限価格×1.1」の負担金<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。価格の予見性の論点に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜課題】排出量取引制度の課題を『技術・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　排出目標量・実績量は登録確認機関の確認が必須で、算定・確認の体制づくりが初年度から必要になる<br><br><b>答案での使い方</b>　Ⅱ-1の課題。「確認体制」を観点つきで書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜解決策】排出量取引制度で国際競争力への影響を抑える仕組みを、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　原単位の改善率を用いた無償割当てで、事業分野間の均衡と国際競争力に配慮する<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 競争力対策の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜解決策】排出量の算定・確認の体制づくりの解決策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　確認を担う登録確認機関を国の登録制とし、ERMSとマニュアルで算定・報告の手続きを整える<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 運用面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜注意】排出量取引2026年度、化石燃料賦課金、発電の有償割当ての開始年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　排出量取引は2026年度、化石燃料賦課金は2028年度、発電事業者の有償割当ては2033年度<br><br><b>答案での使い方</b>　年度の取り違えは減点。順序で覚える<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜時期】化石燃料賦課金の徴収開始はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2028年度（令和10年度）から徴収する予定で、まだ始まっていない<br><br><b>答案での使い方</b>　Ⅱ-1で予定段階と示す。排出量取引(2026)と区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜定義】成長志向型カーボンプライシング構想とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　GX先行投資を促しつつ炭素価格の負担を段階的に導入し、脱炭素と産業競争力を両立させる構想<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しの定義に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜制度】化石燃料賦課金は誰が納め、どう計算されるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　化石燃料の採取・輸入事業者が納付。賦課額は「単価×CO2排出量（t）」で、最終消費者には直接課さない<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。納付義務者の取り違え防止<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜制度】GX経済移行債の発行期間と償還の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　令和5〜14年度に発行。賦課金と特定事業者負担金の収入で令和32年度（2050年度）までに償還<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。財源の裏付けとして<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜課題】化石燃料賦課金導入の課題を『経済』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　負担が産業・家計のエネルギーコストに及ぶ。法は「中長期的なエネルギー負担の抑制」「公正な移行」を基本理念とする<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜解決策】賦課金の負担を抑える仕組みを、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　単価を上限・下限の算定式の範囲内で政令により定め、エネルギー施策との整合等に応じて減額・還付を認める<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 負担抑制の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜解決策】企業の早期投資を促す設計を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　徴収開始時期と段階的に引き上げる方針を事前に示し、早く取り組むほど将来の負担が軽くなる設計にする<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 予見性の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜注意】賦課金の単価は法律本文で定められているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　定められていない。単価は政令で決め、法律が定めるのは上限・下限の算定式と徴収開始年度<br><br><b>答案での使い方</b>　「法律で単価を定める」と書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜時期】CCS事業法の施行状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　段階施行で、探査は2024年8月、試掘は2024年11月、貯留事業・導管輸送は2026年5月22日に完全施行<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜定義】CCS事業法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　CO2を地下に貯蔵する貯留事業と、導管輸送事業に、許可制・届出制、保安規制、事業終了後の管理を定めた法律<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】貯留事業の許可の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　経産大臣が「特定区域」を指定して募集し、貯留区域ごとに許可。海域の指定は環境大臣の同意が必要<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。海域は経産・環境の共管<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】注入終了後の管理の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　事業者が引当金を積み、閉鎖措置の確認・廃止許可後は管理がJOGMECへ移り、事業者はJOGMECへ拠出金を納付<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。長期管理の資金確保<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】漏えい等による損害の賠償責任は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　損害発生時の貯留事業者等が負う無過失責任。過失を立証されなくても責任を負う<br><br><b>答案での使い方</b>　Ⅱ-1の制度の留意点に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜課題】CCSの課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　注入CO2が長期に安定して貯蔵され漏えいがないことの確認が要り、モニタリング・閉鎖措置の詳細設計が必要<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜解決策】CCSの漏えいリスクへの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　貯留層の温度・圧力等の監視と報告を義務づけ、漏えい時は直ちに応急措置、閉鎖措置を確認して廃止を許可する<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 保安面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜注意】海底下CCSの許可は、海洋汚染等防止法と本法のどちらか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　本法に一元化され、経産大臣と環境大臣の共管となった<br><br><b>答案での使い方</b>　旧制度（海洋汚染等防止法の許可）と混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜時期】水素社会推進法の施行状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　令和6年法律第37号。2024年5月公布、2024年10月23日に施行済み。所管は経済産業省<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜定義】「低炭素水素等」とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　水素とアンモニア・合成メタン・合成燃料等で、製造時のCO2排出量が一定値以下と認められるもの（法第2条）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜制度】水素社会推進法の計画認定の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　供給・利用事業者が計画を作り、主務大臣が認定。価格差支援は両者連名の共同計画で、供給の継続が要件<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。需給一体で支援する点を書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜制度】水素社会推進法の支援の実施主体は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　JOGMECが、継続的な供給に必要な資金や共用設備整備の資金として、認定事業者へ助成金を交付する<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。国が直接交付と書かない<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜課題】低炭素水素等の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　大規模な利用ニーズの創出と、サプライチェーン構築に資する拠点の整備、保安規制の合理化が必要<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜解決策】供給拠点づくりの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　拠点整備支援（助成）と、港湾法・高圧ガス保安法・道路占用の特例を、規制緩和と一体で進める<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 制度面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜解決策】国際サプライチェーンの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　炭素集約度で評価する基準を日本が主導して策定し、国際標準と相互認証の認証スキームの構築を進める<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国際面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜注意】水素社会推進法の対象は水素だけか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　水素だけでなく、アンモニア・合成メタン・合成燃料等を含む「水素等」<br><br><b>答案での使い方</b>　対象を水素のみと書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜時期】次世代型太陽電池戦略はいつ策定され、どの計画に目標が反映されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2024年11月に官民協議会が策定。第7次エネルギー基本計画とGX2040ビジョン（2025年2月）に目標を反映<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と位置づけを示す<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜定義】ペロブスカイト太陽電池とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　軽量・柔軟で、従来のシリコン系では難しかった耐荷重性の低い屋根や壁面にも設置できる次世代型太陽電池<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜目標】ペロブスカイト太陽電池の発電コスト目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2025年20円/kWh、2030年14円/kWh、2040年に自立化可能な10〜14円/kWh以下<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。年次とセットで書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜注意】ペロブスカイト太陽電池の「約20GW」は何の目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2040年の導入目標。2030年の目標は導入量ではなく、GW級の量産体制と14円/kWh<br><br><b>答案での使い方</b>　年次の取り違えは減点。2030年は量産体制と書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜課題】ペロブスカイト太陽電池の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　長期に安定した性能を保つ耐久性の確立、製品サイズへの大型化・モジュール化、発電コストの低減が必要<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜課題】ペロブスカイト太陽電池の課題を『産業競争力』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　中国など諸外国の研究開発・量産化が激化し、製品化と市場獲得の速度が競争力を左右する<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済・産業の観点の課題に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜解決策】技術課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　GI基金で量産技術と社会実証を支援し、2030年に14円/kWhを目指す。タンデム型の開発も加速する<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 技術面の解決策に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜解決策】初期需要づくりの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　政府機関・自治体・環境価値を重視する民間企業が初期需要を牽引し、導入補助で投資の予見性を確保する<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 需要面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000389653.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜時期】再エネ海域利用法の改正の公布と施行はいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2025年6月11日公布、2026年4月1日施行（施行済み）。閣議決定は2025年3月7日<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。閣議決定と混同しない<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜定義】EEZへの洋上風力拡大とは何が変わったのか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　従来は領海・内水のみが対象。改正でEEZでの設置を許可する制度と、海洋環境保全のため国が調査する仕組みを新設<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜制度】EEZでの設置許可の流れは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　経産大臣が募集区域を指定→申請→経産・国交大臣が仮許可（5年以内）→協議会→許可<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。二段階審査と書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜目標】洋上風力の案件形成目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2030年までに1,000万kW、2040年までに3,000万〜4,500万kW<br><br><b>答案での使い方</b>　Ⅱ-1の数字。2030年と2040年を取り違えない<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜課題】EEZ洋上風力の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　漁業・航路・港湾・系統との調整。許可基準に漁業・航路への支障がないこと、基地港湾の利用、電線路との接続がある<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 先行利用者との調整の観点の課題に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜課題】EEZ洋上風力の課題を『環境』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　海洋環境の保全。区域指定の際に適切な配慮を行う必要があり、国が必要な調査を行う仕組みが新設された<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 環境影響の観点の課題に<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜解決策】利害関係者の調整の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　協議会で利害関係者を含め協議し、その結果を尊重する。仮許可と許可の二段階審査で事業の確実性を担保<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 合意形成の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜注意】領海・内水とEEZでは、洋上風力の仕組みは同じか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　別。領海・内水は「促進区域」（公募占用計画の認定）、EEZは「募集区域」（仮許可→許可）。EEZの許可は経産・国交の共管<br><br><b>答案での使い方</b>　用語の取り違えは減点。環境大臣は調査を担う<br><br>【出典】<a href=\"https://www.mlit.go.jp/kowan/content/001879078.pdf\" target=\"_blank\" rel=\"noopener\">国土交通省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜時期】JCMのパートナー国は何か国か（2026年5月時点）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　32か国（2026年5月29日時点）。2013年1月のモンゴルとの署名に始まり、法制化は令和6年の温対法改正<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで現状を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜定義】JCMとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　日本とパートナー国が協力して実施した対策による排出削減・吸収量を、両国の貢献度に応じて配分する仕組み<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜目標】JCMの削減量の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　官民連携で2030年度までの累積1億t-CO2程度、2040年度までの累積2億t-CO2程度<br><br><b>答案での使い方</b>　Ⅱ-1の数字。「累積」「年度まで」を落とさない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜制度】JCMの「相当調整」とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　日本が無効化した量を日本の排出量から差し引き、同量をパートナー国の排出量に上乗せして二重計上を防ぐ<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。パリ協定第6条の肝<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜制度】JCMのクレジット量はどう算定するか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　BaU排出量を十分に下回る「リファレンス排出量」と比較して保守的に算定し、両国政府が承認する<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。環境十全性の根拠<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜課題】JCMの課題を『環境十全性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　二重計上の防止と保守的算定の確保。相手国のインベントリの整備状況によっては、削減量が反映されない場合がある<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜解決策】JCMの事務の効率化の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　指定実施機関（JCMA）が多数の国と同時に調整し、クレジット発行までの事務をワンストップ化する<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 運用面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/410AC0000000117\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜注意】JCMの1億tと2億tは、単年の削減量か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　単年ではない。1億tは2030年度までの累積、2億tは2040年度までの累積<br><br><b>答案での使い方</b>　数字の読み違えは減点。累積と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜時期】SSBJ基準の有報での義務化はいつからか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　プライム市場の平均時価総額3兆円以上は2027年3月期、1兆円以上は2028年3月期、5,000億円以上は2029年3月期（予定）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで段階適用と時期を示す<br><br>【出典】<a href=\"https://www.fsa.go.jp/news/r7/shouken/20260220/20260220.html\" target=\"_blank\" rel=\"noopener\">金融庁を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜定義】SSBJ基準とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　日本初のサステナビリティ開示基準。ISSB基準を踏まえ、サステナビリティ基準委員会が2025年3月に公表<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.ssb-j.jp/jp/wp-content/uploads/sites/6/2026_07.pdf\" target=\"_blank\" rel=\"noopener\">SSBJ（サステナビリティ基準委員会）（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜制度】SSBJ基準を構成する3つの基準は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　ユニバーサル基準「適用基準」、第1号「一般開示基準」、第2号「気候関連開示基準」<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。構成を1文で言う<br><br>【出典】<a href=\"https://www.ssb-j.jp/jp/wp-content/uploads/sites/6/2026_07.pdf\" target=\"_blank\" rel=\"noopener\">SSBJ（サステナビリティ基準委員会）（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜制度】義務化の経過措置と保証の定めは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　義務化の翌年から第三者保証。最初の2年は訂正報告書での記載（二段階開示）、スコープ3は初年度免除<br><br><b>答案での使い方</b>　Ⅱ-1の制度の留意点。段階的導入の根拠<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜課題】SSBJ義務化の課題を『技術・信頼性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　開示の比較可能性・有用性の向上と、第三者保証がなければ確保しにくい信頼性<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜課題】SSBJ義務化の課題を『担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　保証業務の実施者の確保。監査法人以外にも登録の道を開く必要がある<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 人材の観点の課題に<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜解決策】開示の信頼性の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　国際基準と整合する保証基準で第三者保証を義務づけ、保証業務実施者を登録制にする<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜注意】SSBJ基準は法令そのものか？義務化はいつ保証までか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　法令ではない。金融庁長官の告示指定で有報の基準になる。最初の義務化は2027年3月期で、保証はその翌年<br><br><b>答案での使い方</b>　基準の位置づけと保証の時期を取り違えない<br><br>【出典】<a href=\"https://www.fsa.go.jp/news/r7/shouken/20260220/20260220.html\" target=\"_blank\" rel=\"noopener\">金融庁を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜時期】クライメート・トランジション・ファイナンスに関する基本指針はいつ策定・改訂されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2021年に策定、2025年3月に改訂（2025年版）。金融庁・経産省・環境省が策定<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜定義】トランジション・ファイナンスとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　気候変動対策を検討する企業が長期戦略に沿ってGHG削減に取り組む場合に、その取組を支える金融手法。長期戦略の信頼性に着目<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜制度】基本指針が資金調達者に開示を推奨する4要素は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　①戦略とガバナンス②環境面のマテリアリティ③科学的根拠に基づく戦略と目標④実施の透明性<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。ICMAハンドブックと整合<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜制度】分野別技術ロードマップはどの分野を対象にしているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　鉄鋼・化学・電力・ガス・石油・紙パルプ・セメント・自動車に海運・航空を加えた10分野。日本の排出量の8割強<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。評価の参照先として書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜課題】トランジション・ファイナンスの課題を『経済・金融』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　実行した金融機関の投融資先の排出量（ファイナンスド・エミッション）が、一時的に増加する<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜課題】トランジション・ファイナンスの課題を『信頼性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　国際的な共通認識の醸成は途上で、信頼性の確保のため良質な事例の積み上げが重要<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度・信頼性の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜解決策】信頼性確保の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　4要素の開示を求めてICMAハンドブックと整合を図り、フォローアップガイダンスで資金供給後の確認を整える<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜注意】クライメート・トランジション利付国債は、基本指針と同じ枠組みか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　別枠組み。2024年2月に国が発行を始めた世界初の国によるトランジションボンド<br><br><b>答案での使い方</b>　基本指針（金融庁・経産省・環境省）と混同しない<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/transition_finance/siryou/20260821/014_03_00.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜時期】熱中症特別警戒情報はいつから運用され、発表実績は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2024年4月（改正気候変動適応法の全面施行）から運用。令和6・7年度とも発表0回<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで運用開始時期を示す<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜定義】熱中症特別警戒情報とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　気温が特に著しく高く、熱中症による人の健康への重大な被害が生ずるおそれがある場合に、環境大臣が発表する情報（法第19条）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜制度】警戒情報と特別警戒情報の発表基準は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　警戒：府県予報区内の1地点以上で日最高WBGT33以上。特別警戒：都道府県内の全地点で35以上<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。基準と範囲を書き分ける<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜制度】指定暑熱避難施設（クーリングシェルター）の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　市町村長が冷房設備のある施設を指定し、特別警戒情報の発表時に開放する<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。自治体の役割として書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜課題】熱中症対策の課題を『社会・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　高齢者やこども等の熱中症弱者は自助による予防が難しく、家族や身近な人の見守り・声かけ（共助）と公助が要る<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 社会・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜解決策】熱中症の共助を強める解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　熱中症対策普及団体や福祉関係団体を通じた見守り・声かけの強化と、エアコン利用の有効性の周知<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 担い手面の解決策に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜解決策】極端な高温時の体制整備の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　指定暑熱避難施設の指定・確保と、極端な高温時の自治体内の役割分担の明確化<br><br><b>答案での使い方</b>　Ⅱ-2 自治体の手順・調整事項に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜注意】熱中症対策実行計画の「半減」は、何を基準にした目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　令和4年（概数）の5年移動平均1,295名を基準に、2030年に熱中症死亡者数を半減<br><br><b>答案での使い方</b>　基準年・基準値を落とすと減点<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜時期】気候変動影響評価報告書の第3次はいつ公表されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2026年2月16日に公表。第2次は令和2年12月。おおむね5年ごとに作成する（法第10条）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02915.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜定義】気候変動影響評価報告書とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　気候変動適応法に基づき、最新の科学的知見でおおむね5年ごとに行う影響の総合的評価。適応計画の変更時に勘案する<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】影響評価の3つの観点は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　重大性、緊急性、確信度<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。評価の物差しとして書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02915.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】第3次報告書の改善点は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　重大性を3段階（レベル1〜3）に細分化し、現状・1.5〜2℃上昇時・3〜4℃上昇時で評価。「特に強い影響を受ける地域・対象」を追加<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。第2次との違い<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】第3次が特に優先的に対応が必要とした項目は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　水稲の収量・品質低下、果樹の栽培適地の変化、洪水・内水、サンゴの白化、暑熱、インフラ・ライフラインの寸断など<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の根拠に。分野を挙げるときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜課題】影響評価の課題を『科学的知見』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　適応策の効果を定量的・具体的に整理できたのは小項目全体の3割程度で、複数の適応策を比較できる知見は非常に限られる<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術・知見の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜解決策】評価結果をどう使うか（解決策）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2026年度の気候変動適応計画の改定と、自治体・事業者による影響の把握・適応策の検討に活用する<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 調査検討事項の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜注意】「80項目」とは何か？公表年と計画改定の年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　7分野を細分化した小項目の数で第2次より9項目増。公表は2026年2月、適応計画の改定は2026年度の予定<br><br><b>答案での使い方</b>　数字と年度の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜時期】再資源化事業等高度化法はいつ全面施行されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2025年11月21日に全面施行（一部は2025年2月1日）。公布は2024年5月29日<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。公布日と区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜定義】再資源化事業等高度化法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　再資源化のための廃棄物の収集・運搬・処分と、再資源化の技術・設備の高度化を促し、GHG削減効果の高い資源循環を促進する法律<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜制度】再資源化事業等高度化法の認定3類型は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　①高度再資源化事業計画②高度分離・回収事業計画③再資源化工程高度化計画（既存施設向け）。環境大臣が認定<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。3類型を番号で書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜制度】判断基準と報告・公表の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　廃棄物処分業者の判断基準を環境省令で定め、特定産業廃棄物処分業者が処分量・再資源化量を毎年度報告し、環境大臣が公表<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。底上げの仕組みとして書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜課題】資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　製造（動脈）と廃棄物処分（静脈）の連携。再生資源の利用目標の共有と、トレーサビリティのためのデータ連携が要る<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000360673.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜課題】資源循環の課題を『経済・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　製造業が求める量・質の再生材を安定供給できる事業が不足している。再資源化工程自体の脱炭素化も求められる<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000360673.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜解決策】製造側と処分側をつなぐ解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　高度再資源化事業の認定で、製造側の需要に応じた質・量の再生材確保を図り、製造事業者と処分業者のマッチングを促す<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 連携面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜注意】認定は誰が行い、廃棄物処理法との関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　環境大臣が国で一括して認定し、廃掃法の許可の特例を与える。廃掃法そのものを置き換えるものではない<br><br><b>答案での使い方</b>　都道府県知事の認定と書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜時期】太陽電池廃棄物の再資源化等推進法は施行されているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　令和8年法律第33号。2026年6月5日公布で未施行。施行は公布から1年6か月以内の政令日（2027年秋〜冬の予定）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「公布済み・未施行」と示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜定義】太陽電池廃棄物の再資源化等推進法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　多量の事業用パネルの廃棄者からリサイクル規制を段階的に強化し、幅広い排出者への義務化に向けた環境整備を行う法律<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜制度】義務づけの対象と、勧告・命令の対象は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　事業用パネルの廃棄者に、判断基準に基づくリサイクルの取組を義務づけ。勧告・命令の対象は多量廃棄者<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。全面義務化と書かない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜制度】多量事業用太陽電池廃棄者に課される手続は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　廃棄前に実施計画を国へ届出し、原則、受理から30日経過後でなければ排出できない<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。排出前の事前届出と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜課題】パネルのリサイクルの課題を『技術・体制』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　専用施設の処理能力は約13万t/年で今後の排出見込量に不足し、8府県に施設がない<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術・体制の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜課題】パネルのリサイクルの課題を『経済』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　埋立とリサイクルの費用差が大きい（リサイクル8,000〜12,000円/kW、埋立2,000円/kW程度〜）<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜解決策】リサイクル促進の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　設備・保管施設の導入支援に加え、国の認定制度（廃掃法の許可の特例）で広域的・効率的な処理を進めコストを下げる<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 制度・設備面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜注意】この法律は、全てのパネルにリサイクルを義務づけるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　一律ではない。義務づけは事業用の廃棄者への判断基準の取組で、住宅用を含む全面義務化は附則の検討規定にとどまる<br><br><b>答案での使い方</b>　「全パネル義務化」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜時期】プラスチック資源循環促進法の施行はいつか？また見直しの時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2021年6月公布、2022年4月施行。附則で施行後5年の検討を定め、2027年4月以降に見直しが可能<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。見直しは未決定<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜定義】プラスチック資源循環促進法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　製品の設計から廃棄物処理まで、あらゆる主体のプラスチック資源循環の取組を促す法律。3R+Renewableが基本原則<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜制度】同法の措置の5本柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　設計指針・認定、使用の合理化、市町村の分別収集・再商品化、自主回収・再資源化、排出事業者の排出抑制・再資源化<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。5段階で書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜制度】特定プラスチック使用製品とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　無償提供される12製品（スプーン・ストロー・ヘアブラシ・歯ブラシ・ハンガー等）。提供量5t以上の事業者が勧告等の対象<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。12製品と5tの数字<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/pro/gorika\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜目標】プラスチック資源循環戦略のマイルストーンは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2030年までにワンウェイプラを累積25%排出抑制、2035年までに使用済プラを100%有効利用<br><br><b>答案での使い方</b>　Ⅱ-1の数字。年次とセットで書く<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/about/senryaku\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜課題】プラ資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　プラ資源の回収量の拡大が課題。容リ協の入札量は令和4年度約69万tから令和7年度約66万tへ微減した<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 回収の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜解決策】再生材の需要づくりの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　再生材・バイオプラの価値創出（GHG削減効果の評価、マスバランス方式）を検討し、再生プラ利用計画で需要を創出<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 需要面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜注意】特定プラ12品目の要件と、レジ袋有料化との関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　要件は「無償提供」。レジ袋有料化（2020年7月）は本法施行（2022年4月）より前の別の施策<br><br><b>答案での使い方</b>　有償提供品や時期を取り違えない<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/pro/gorika\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜時期】食品ロス削減推進法と基本方針の時期は？また最新推計は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　法は2019年5月公布・10月施行。基本方針は2025年3月閣議決定。最新推計は令和6年度（2026年6月公表）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/501AC1000000019\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜定義】食品ロスとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　まだ食べることができるのに廃棄される食品（可食部）。食品廃棄物全体とは別（法第2条第2項）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/501AC1000000019\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜目標】基本方針が定める食品ロス削減の2030年度目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　家庭系は2000年度比で半減、事業系は2000年度比で60%削減<br><br><b>答案での使い方</b>　Ⅱ-1の数字。家庭系と事業系の割合を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000408175.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜制度】令和6年度の食品ロス発生量は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　461万t（事業系237万t、家庭系224万t）。前年度の464万tから約3万t減<br><br><b>答案での使い方</b>　Ⅱ-1の数字。年度とセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜課題】食品ロス削減の課題を『事業系』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　外食産業の食品ロスが増加傾向で、令和6年度は事業系全体が前年度比で増えた<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 事業系の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜課題】食品ロス削減の課題を『家庭系』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　削減率48.3%で半減目標に届かず、直接廃棄と食べ残しが大半を占める<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 家庭系の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜解決策】食品ロス削減の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　外食の食べ残し持ち帰り（mottECO）の導入支援と、デコ活による家庭の行動変容の後押し<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 事業系・家庭系の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜注意】令和5年度と令和6年度の食品ロス量、世界目標と国内目標の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　令和5年度464万t、令和6年度461万t（最新）。世界は一人当たり食料廃棄の半減、国内は2000年度比の総量<br><br><b>答案での使い方</b>　年度と目標の母集団を取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜時期】地域生物多様性増進法はいつ施行されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2024年4月公布、2025年4月1日施行（施行済み）。主務大臣は環境・農林水産・国土交通大臣<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜定義】OECMとは何か？自然共生サイトとの関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　OECMは保護地域以外で生物多様性の保全に資する管理が行われている区域。自然共生サイトはその日本版を国が認定する制度<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜制度】地域生物多様性増進法の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　基本方針と、増進活動実施計画の認定制度。認定活動は自然公園法・森林法等の許可・届出の特例（ワンストップ化）を受ける<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。認定と特例の2点を書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜制度】自然共生サイトの累計認定数は？（2026年10月時点）", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　700か所（2026年10月30日の令和8年度第2回認定で到達。法施行前の328か所を含む累計）<br><br><b>答案での使い方</b>　Ⅱ-1の数字。累計の起点を明示する<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05720.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜課題】30by30の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　30by30は主にOECMの設定で達成する計画だが、OECMは陸域で0.2%にとどまる（2026年8月時点）<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜課題】生物多様性の取組の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　生物多様性の状況と保全活動の効果の「見える化」が必要。見える化システムで国土全体の状況を可視化している<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜解決策】OECMを増やす解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　自然共生サイトの認定を進め、保護地域との重複を除いてOECM国際データベースに登録する。支援証明書制度で企業の参画を促す<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 30by30の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05720.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜注意】自然共生サイトとOECMは同じか？保護地域との合計割合は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　同じではない。国際DBへの登録は保護地域と重複しない区域のみ。合計は陸域約21.0%、海域約13.3%で目標30%未満<br><br><b>答案での使い方</b>　定義の書き分けで減点を避ける<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜時期】ネイチャーポジティブ経済移行戦略はいつ誰が策定したか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2024年3月に環境省・農水省・経産省・国交省が策定。2025年7月にロードマップ（2025-2030年）を策定<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで策定主体と時期を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜定義】ネイチャーポジティブ経営とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　自然資本の保全を価値創造のマテリアリティに据えて、ネイチャーポジティブを目指す経営。実現した経営の意味ではない<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜制度】ネイチャーポジティブ移行による2030年のビジネス機会は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　世界で年1,372兆円（WEF2020年推計）、日本では環境省試算で年47兆円<br><br><b>答案での使い方</b>　Ⅱ-1の数字。世界と日本を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜制度】国の施策の4つの構成は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　①リスク・機会の認識②機会の特定・創出③開示・対話を通じた資金呼び込み④基盤環境整備（DX・研究開発）<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。4段階で書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜課題】ネイチャーポジティブの課題を『技術・評価』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　自然資本への負荷を定量評価する指標・手法の整備が途上で、効果の見える化と、場所に紐づくデータが必要<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜課題】ネイチャーポジティブの課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　自然資本の保全・再生が他の課題より劣後されがち。経団連調査（2022年度）で25%の企業が事業との関連性がわからないと回答<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 企業認識の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜解決策】企業の取組を促す解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　TNFD等による開示の促進と、調達ガイドライン（2026年7月）・ネイチャーファイナンス実践ガイドライン（同9月）の普及<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 開示・金融の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜注意】年1,372兆円と年47兆円の違い、戦略と法律・ロードマップの関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　1,372兆円は世界、47兆円は日本。戦略は4省庁の戦略で法律ではなく、ロードマップは別文書<br><br><b>答案での使い方</b>　数字は母集団とセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜時期】クマ類の指定管理鳥獣追加と緊急銃猟の規定はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　クマ類（四国を除く）の追加は2024年4月。緊急銃猟の規定は令和7年法律第28号で、2025年9月1日施行<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期を示す。四国個体群は除く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜定義】指定管理鳥獣とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　希少鳥獣以外で集中的かつ広域的な管理が必要として環境大臣が指定する鳥獣。都道府県または国が捕獲等事業を実施できる<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜目標】クマ被害の現状を示す数字は？（令和7年度）", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　人身被害216件・被害者238人・死亡13人（速報値の年度計、いずれも過去最多）<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 課題の大きさを示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/effort/effort12/effort12.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜制度】緊急銃猟の4要件は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　危険鳥獣の侵入（おそれ含む）、人の生命・身体への危害防止の緊急性、銃猟以外が困難、弾丸到達のおそれなし<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。4要件すべて必要と書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜制度】クマ被害対策ロードマップ（2026年3月）の2030年度目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　緊急対応体制の確保率100%、推定個体数・捕獲目標数の明確化率100%、ゾーニング管理計画の策定率100%<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。3つの100%<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/reinforce/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜課題】クマ対策の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　個体数管理のため、統一的な手法による個体数推定と捕獲目標数の精緻化が必要<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_09/000378789.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜解決策】出没防止と緊急対応の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　誘引物（放任果樹等）の管理、はこわな・電気柵の整備、ゾーニング管理計画の作成支援、緊急銃猟の体制整備<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/reinforce/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜注意】緊急銃猟を実施させる主体は誰か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　市町村長（都道府県ではない）。通行制限・避難指示、応援要請、損失補償も市町村長が行う<br><br><b>答案での使い方</b>　実施主体の取り違えは減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜時期】外来生物法の2022年改正の公布と施行はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2022年5月18日公布。2022年7月1日に規制権限の拡充、2023年4月1日にその他が施行（全面施行済み）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。2段階を落とさない<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜定義】要緊急対処特定外来生物とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　まん延すると著しく重大な被害が生じ、発見時に検査・防除等を緊急に行う必要があるものとして政令で定める生物。ヒアリ類を指定<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜制度】要緊急対処特定外来生物の主務大臣の権限は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　通関後も物品・土地・施設への立入検査、消毒・廃棄命令、移動の制限・禁止命令ができる<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。水際強化の根拠<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜制度】条件付特定外来生物とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　アカミミガメとアメリカザリガニ（2023年6月指定）。家庭での飼養と少数への無償譲渡は適用除外。販売・購入・放出は原則禁止<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。規制の線引きを書く<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜課題】条件付き規制にした理由（課題）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　全て禁止にすると手続きの負担から野外放出が増えるおそれがある。終生飼養と放出禁止の周知が必要<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜課題】ヒアリ対策の課題を『技術・水際』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　輸入品に付着して非意図的に侵入する生物が増え、ヒアリの確認は2025年度に36件で過去最多。探知・検査の高度化が要る<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 水際の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜解決策】水際対策の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　全国65港湾でのモニタリング・駆除と、ヒアリ探知犬など新たな対策技術の実証<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 水際施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜注意】条件付特定外来生物は、法律上、特定外来生物ではないのか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　特定外来生物のまま。適用除外は飼養・譲渡しの一部で、放出・輸入・販売・頒布・購入は原則禁止のまま<br><br><b>答案での使い方</b>　「規制対象外」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜時期】PFOS・PFOAの水質基準化はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2025年6月30日公布、2026年4月1日施行（施行済み）。水質基準52項目の1つとなった<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜定義】PFOS・PFOAとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　有機フッ素化合物（PFAS）の一種。化学的に極めて安定で難分解性。化審法で原則製造・輸入禁止（第一種特定化学物質）<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/water/pfas/faq003.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜制度】PFOS・PFOAの水道水質基準値は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　PFOSとPFOAの合算で50ng/L（0.00005mg/L）以下。水道事業者等に遵守・検査の義務がある<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。合算と単位を書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜制度】公共用水域・地下水のPFOS・PFOAの扱いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　環境基準ではなく要監視項目の指針値（50ng/L合算）。2025年6月に「暫定」を外した<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。水道水との違いを書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜課題】PFOS対策の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　濃度低減の対策技術の知見の充実が必要。使用済み活性炭の不適切な保管から流出した事案もあり、活性炭の管理が課題<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜課題】PFOS対策の課題を『制度』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　PFOS・PFOA以外のPFASは毒性評価が定まらず、要検討項目に据え置かれている<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜解決策】PFOS低減の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　対策技術の実証事業と対策技術集の活用、使用済み活性炭の適正な保管・取扱いの周知<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 技術面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜注意】50ng/Lは基準化で変わった値か？合算か個別か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　値は暫定目標値から変わらず、変わったのは位置づけ（義務のある基準へ）。PFOSとPFOAの合算<br><br><b>答案での使い方</b>　「基準値が厳しくなった」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜時期】底層溶存酸素量はいつ環境基準になり、類型指定はどこまで進んだか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2016年3月に生活環境項目に追加。琵琶湖・東京湾（2021年）、伊勢湾・大阪湾（2022年）、霞ケ浦等（2024年）を指定<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と実績を示す<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜定義】底層溶存酸素量とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　魚介類等の生息や藻場等の生育への直接的な影響を判断できる指標。底層を利用する生物の生息・再生産に重要<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜制度】底層溶存酸素量の3つの類型と基準値は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　生物1は4.0mg/L以上、生物2は3.0mg/L以上、生物3は2.0mg/L以上（日間平均値）<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。類型と値を対で書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜制度】大阪湾の底層溶存酸素量の類型指定の範囲は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　湾奥部のみ（生物3）。湾全域ではない。東京湾などは水域ごとに生物1〜3が混在<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。指定は水域ごと<br><br>【出典】<a href=\"https://www.env.go.jp/press/110371.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜課題】底層の貧酸素化の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　湖沼では底質からの栄養塩溶出（内部負荷）や鉄・マンガン溶出による水道水の障害にもつながり、要因解析と対策技術の選定が要る<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/900544873.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜解決策】貧酸素化の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　外部負荷削減に加え、内部負荷削減（浚渫・覆砂）と、曝気・酸素水供給による底層への酸素供給を組み合わせる<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 水環境の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/900544873.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜注意】底層溶存酸素量の基準値は何の値か？どの類型が最も厳しいか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　日間平均値。生物1（4.0mg/L以上）が最も厳しい。1つの湾・湖でも類型は混在する<br><br><b>答案での使い方</b>　基準値の種類と類型の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜時期】プラスチック汚染条約は成立したか？交渉の現状は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　未成立。2022年のUNEA5.2決議でINCを設置したが、2024年末の策定目標は未達。INC5.4は2027年3月に開催予定<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「交渉中」と示す<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜定義】大阪ブルー・オーシャン・ビジョンとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2019年のG20大阪サミットで共有された、2050年までに海洋プラごみによる追加的な汚染をゼロにする目標。日本が提唱<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し・日本の取組の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02873.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜課題】条約交渉の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　INC5.2（2025年8月）で、生産、プラスチック製品（第4条）、資金（第10条）は各国の意見の隔たりが大きく合意に至らなかった<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 国際制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜課題】条約実施の課題を『経済・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　途上国の廃棄物管理の能力構築とインフラ整備が必要。日本は人材育成（2025年までに1万人）等を表明している<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 国際協力の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜解決策】途上国支援の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　ASEAN各国を中心とした国別行動計画の策定支援、海洋ごみモニタリング能力の強化、地域ナレッジセンターの設置<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国際協力の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜解決策】国内でできる解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　プラスチック資源循環促進法による設計・使用の合理化・回収・再資源化と、海洋プラごみの回収・流出防止を進める<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国内施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜注意】「2050年ゼロ」と「2040年ゼロ」は同じ目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　別。2050年は大阪ブルー・オーシャン・ビジョン（2019年）、2040年は2023年G7広島サミットでの野心<br><br><b>答案での使い方</b>　年次の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02873.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜注意】INC5.3（2026年2月）では条文交渉をしたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　していない。前議長の辞任を受けた新議長の選出などを行う、組織的・事務的事項の会合<br><br><b>答案での使い方</b>　INC5.2・5.3・5.4の役割を混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜時期】河川・湖沼マイクロプラスチック調査ガイドラインはいつ策定されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　河川版は2021年6月、湖沼を加えた現名称は2023年3月30日。その後改訂され、令和8年4月版が最新<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜定義】マイクロプラスチックとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　一般的に5mm未満の微細なプラスチック。海洋プラごみの約8割は陸域発生とされ、河川を経由して流出する<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜制度】マイクロプラスチックに法的基準値はあるか？ガイドラインの位置づけは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　ない。ガイドラインは調査方法の手引きで、結果を基に自治体が関係機関と連携して発生源対策を進める<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。規制ではないと書く<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜制度】令和4年度の河川調査（一級水系7水系）の結果は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　長径1〜5mmの平均個数密度は0.1〜0.8個/m3。人口密度・市街化率と強い正の相関<br><br><b>答案での使い方</b>　Ⅱ-1の数字。個数密度の単位は個/m3<br><br>【出典】<a href=\"https://www.env.go.jp/content/000220901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜課題】マイクロプラスチックの課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　添加剤や吸着した化学物質が生物・生態系に及ぼす影響の科学的知見が、まだ十分に蓄積されていない<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 科学的知見の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜解決策】科学的知見の不足への解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　生物・生態系への影響評価手法の検討と、調和ガイドラインに沿ったデータ収集、AOMIによる国際共有<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 調査検討事項の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜解決策】事業者との連携の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　マイクロプラスチック・スマート懇話会で業界団体・事業者と普及啓発を検討し、グッド・プラクティス集で先進事例を発信<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 事業者連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜注意】マイクロプラスチックの個数密度は他の調査の数値と比べられるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　直接比べられない。調査年度・地点・サイズ範囲（1mm以上5mm未満など）で大きく変わる<br><br><b>答案での使い方</b>　数字を比較に使うときは条件を揃える<br><br>【出典】<a href=\"https://www.env.go.jp/content/000220901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜時期】気候変動適応法の施行と、次期適応計画の改定時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　2018年6月公布、同12月施行。2023年に熱中症対策を強化。次期計画は2026年度内に改定予定<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期を示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜定義】地域気候変動適応センターとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　都道府県・市町村が、影響・適応の情報の収集・整理・分析・提供と技術的助言を行う拠点機能を担う体制（第13条、努力義務）<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体の体制の定義に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜制度】地域気候変動適応計画の根拠と義務の程度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　法第12条。都道府県・市町村が国の適応計画を勘案して策定するよう努める努力義務<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体計画の書き出しに<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜制度】気候変動適応広域協議会とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　国の地方行政機関・都道府県・市町村・センター・事業者等で組織でき、全国7ブロックで広域アクションプランを策定<br><br><b>答案での使い方</b>　Ⅱ-2 関係者調整（広域連携）の根拠に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜目標】地域適応計画とセンターの現状（2026年3月）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　491自治体が計画を策定し、センターは70か所。491は自治体数、70はセンター数（共同設置は1件）<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 現状の数字。自治体数とセンター数を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427991.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜課題】地域適応の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　市町村の計画策定の促進と計画の質の向上、センターの地域適応のハブとしての機能強化が必要<br><br><b>答案での使い方</b>　Ⅱ-2・必須Ⅰ(1) 自治体の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000191251.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜解決策】自治体の適応を支える解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　A-PLATでの影響予測・優良事例の共有、国立環境研究所の専門家派遣（オンライン可）、策定マニュアルの改訂とツール提供<br><br><b>答案での使い方</b>　Ⅱ-2 自治体支援の手順に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427991.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜注意】地域適応計画・センターの100%目標は、誰が対象か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<b>答え</b>　都道府県・政令指定都市が対象で、市町村は対象外。計画もセンターも努力義務（2026年度目標）<br><br><b>答案での使い方</b>　義務と書くと減点。対象自治体も明記<br><br>【出典】<a href=\"https://www.env.go.jp/content/000191251.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}];
